def retry(max_attempts=3, base=0.5):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **kw):
            for i in range(max_attempts):
                try:
                    return fn(*a, **kw)
                except Exception:
                    if i == max_attempts - 1:
                        raise
                    time.sleep(base * (2 ** i))
        return wrapper
    return deco

