pub struct ParseError;

pub fn parse_duration(s: &str) -> Result<u64, ParseError> {
    let mut total = 0u64;
    let mut num = String::new();
    for ch in s.chars() {
        if ch.is_ascii_digit() {
            num.push(ch);
        } else {
            let n: u64 = num.parse().map_err(|_| ParseError)?;
            num.clear();
            total += match ch {
                'h' => n * 3600,
                'm' => n * 60,
                's' => n,
                _ => return Err(ParseError),
            };
        }
    }
    if !num.is_empty() { return Err(ParseError); }
    Ok(total)
}

