#pragma once
#include <array>
#include <cstddef>
#include <optional>

template <typename T, std::size_t N>
class Ring {
public:
    void push(const T& v) {
        data_[head_] = v;
        head_ = (head_ + 1) % N;
        if (count_ < N) ++count_;
    }

    std::optional<T> pop() {
        if (count_ == 0) return std::nullopt;
        std::size_t tail = (head_ + N - count_) % N;
        T v = data_[tail];
        --count_;
        return v;
    }

    std::size_t size() const { return count_; }
    std::size_t capacity() const { return N; }
    bool empty() const { return count_ == 0; }

private:
    std::array<T, N> data_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;
};

#include "include/ring.hpp"
#include <cassert>
#include <iostream>

int main() {
    Ring<int, 3> r;
    assert(r.empty());
    r.push(1); r.push(2); r.push(3);
    assert(r.size() == 3);
    r.push(4); // overwrites oldest (1)
    assert(r.size() == 3);
    assert(r.pop().value() == 2);
    assert(r.pop().value() == 3);
    assert(r.pop().value() == 4);
    assert(r.pop() == std::nullopt);
    std::cout << "ok\n";
    return 0;
}

