#include "ring.h"

void ring_init(ring_t *r, int *storage, size_t cap) {
    r->buf = storage;
    r->cap = cap;
    r->head = 0;
    r->len = 0;
}

int ring_push(ring_t *r, int v) {
    if (r->len == r->cap) return -1;
    r->buf[(r->head + r->len) % r->cap] = v;
    r->len++;
    return 0;
}

int ring_pop(ring_t *r, int *out) {
    if (r->len == 0) return -1;
    *out = r->buf[r->head];
    r->head = (r->head + 1) % r->cap;
    r->len--;
    return 0;
}

