import csv
import sys
from collections import OrderedDict


def dedup(path, key, keep="last"):
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.reader(f)
        rows = list(reader)
    if not rows:
        return 0
    header, body = rows[0], rows[1:]
    try:
        idx = header.index(key)
    except ValueError as e:
        raise SystemExit(f"no column named {key!r} in {path}") from e
    seen = OrderedDict()
    for row in body:
        if len(row) <= idx:
            continue
        if keep == "last" or row[idx] not in seen:
            seen[row[idx]] = row
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(header)
        w.writerows(seen.values())
    return len(seen)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit("usage: dedup_csv.py FILE KEY")
    n = dedup(sys.argv[1], sys.argv[2])
    print(f"kept {n} unique rows")

