import time
from functools import wraps


def retry(attempts=3, delay=1.0, backoff=2.0):
    def deco(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            wait = delay
            last = None
            for _ in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except Exception as exc:
                    last = exc
                    time.sleep(wait)
