import re

_DURATION_RE = re.compile(r'^(\d+)([smh])$')
_MULT = {'s': 1, 'm': 60, 'h': 3600}


def parse_duration(s):
    m = _DURATION_RE.match(s)
    if not m:
        raise ValueError('bad duration: ' + s)
    num, unit = m.groups()
    return int(num) * _MULT[unit]

