#include <time.h>

static void bubble(int *a, int n) {
    for (int i = 0; i < n - 1; i++) {
        int swapped = 0;
        for (int j = 0; j < n - 1 - i; j++) {
            if (a[j] > a[j + 1]) {
                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
                swapped = 1;
            }
        }
        if (!swapped) break;
    }
}

int main(void) {
    const int n = 20000;
    int *a = malloc(sizeof(int) * n);
    if (!a) { fprintf(stderr, "alloc failed\n"); return 1; }
    srand(42);
    for (int i = 0; i < n; i++) a[i] = rand();
    clock_t start = clock();
    bubble(a, n);
    clock_t end = clock();
    double secs = (double)(end - start) / CLOCKS_PER_SEC;
    printf("n=%d time=%.3fs\n", n, secs);
    for (int i = 0; i < n - 1; i++) {
        if (a[i] > a[i + 1]) { printf("NOT SORTED\n"); free(a); return 1; }
    }
    printf("sorted ok\n");
    free(a);
    return 0;
}

