pub fn balanced(s: &str) -> bool {
    let mut stack = Vec::new();
    for c in s.chars() {
        match c {
            '(' | '[' | '{' => stack.push(c),
            ')' | ']' | '}' => {
                let want = match c { ')' => '(', ']' => '[', _ => '{' };
                if stack.pop() != Some(want) { return false; }
            }
            _ => {}
        }
    }
    stack.is_empty()
}

#[cfg(test)]
mod tests {
    use super::balanced;

    #[test]
    fn ok_nested() {
        assert!(balanced("a(b[c]{d})e"));
    }

    #[test]
    fn empty_is_balanced() {
        assert!(balanced(""));
    }

    #[test]
    fn rejects_mismatch() {
        assert!(!balanced("([)]"));
    }
}

